import { test, expect } from '@playwright/test';

test.describe('Background Sync Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/sync-status');
  });

  test('should display toast notification when background sync completes successfully', async ({ page }) => {
    // Intercept the background sync completion API call
    await page.route('**/api/sync/complete', (route) => {
      route.continue();
    });

    // Click the sync button to initiate background sync
    const syncButton = page.getByRole('button', { name: /sync/i });
    await syncButton.click();

    // Wait for the sync process to start
    await page.waitForTimeout(500);

    // Verify sync status is 'in progress'
    const statusText = page.getByText(/in progress/i);
    await expect(statusText).toBeVisible();

    // Wait for the sync to complete
    await page.waitForTimeout(1000);

    // Verify sync status is 'complete'
    const completeStatusText = page.getByText(/complete/i);
    await expect(completeStatusText).toBeVisible();

    // Verify toast notification appears
    const toastNotification = page.getByText(/background sync completed successfully/i);
    await expect(toastNotification).toBeVisible();

    // Verify toast has success styling
    const toastElement = page.locator('[data-testid="toast-notification"]');
    await expect(toastElement).toHaveClass(/toast-success/);

    // Verify toast has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify toast can be dismissed
    await closeButton.click();
    await expect(toastNotification).not.toBeVisible();
  });

  test('should handle background sync failure and display error toast', async ({ page }) => {
    // Intercept the background sync completion API call and simulate failure
    await page.route('**/api/sync/complete', (route) => {
      route.abort('failed');
    });

    // Click the sync button to initiate background sync
    const syncButton = page.getByRole('button', { name: /sync/i });
    await syncButton.click();

    // Wait for the sync process to start
    await page.waitForTimeout(500);

    // Verify sync status is 'in progress'
    const statusText = page.getByText(/in progress/i);
    await expect(statusText).toBeVisible();

    // Wait for the sync to fail
    await page.waitForTimeout(1500);

    // Verify sync status is 'failed'
    const failedStatusText = page.getByText(/failed/i);
    await expect(failedStatusText).toBeVisible();

    // Verify error toast notification appears
    const errorToast = page.getByText(/background sync failed/i);
    await expect(errorToast).toBeVisible();

    // Verify error toast has error styling
    const toastElement = page.locator('[data-testid="toast-notification"]');
    await expect(toastElement).toHaveClass(/toast-error/);

    // Verify error toast has a retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify retry button is enabled
    await expect(retryButton).toBeEnabled();

    // Verify error toast can be dismissed
    await retryButton.click();
    await expect(errorToast).not.toBeVisible();
  });
});
